// Generated by Cypress Author on 2026-10-22
//
// USU 01–07 (servidor) — Plano_de_Testes_QA_MatchWallet.md §4 (docs-test/areas/usu.md).
// Contas DESCARTÁVEIS (auto-cadastro) e o admin real só executa leitura e a promoção/rebaixamento
// de contas criadas aqui. Não existe "Novo usuário" pelo admin nem `POST /usuarios`: o cadastro
// é `POST /auth/register` (sempre Cliente) e o papel Admin só nasce de `PATCH /usuarios/:id`.
// "Primeiro acesso exigido" (USU 03) não existe no sistema; o teste prova o que existe.
//
// Falham até correção (marcados no título):
//  - nome só com espaços é aceito (`@MinLength(2)` sem `trim`);
//  - e-mail não é normalizado: `Foo@x.com` e `foo@x.com` viram duas contas.

interface UsuarioLista {
  id: string
  nome: string
  email: string
  perfil: string
  ativo: boolean
  criadoEm: string
}

interface Pagina {
  items: UsuarioLista[]
  total: number
  page: number
  pageSize: number
}

const RECUSADO = [400, 422]
const SENHA_OK = 'Senha@12345'
const promovidos: string[] = []

function sufixo() {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`
}

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function registrar(corpo: Record<string, unknown>) {
  return cy.apiRequest<Record<string, unknown>>({
    method: 'POST',
    url: '/auth/register',
    body: corpo,
    failOnStatusCode: false,
  })
}

function listar(consulta: string) {
  return cy.apiRequest<Pagina>({ method: 'GET', url: `/usuarios?${consulta}` }).its('body')
}

describe('Plano QA · Usuários no servidor', () => {
  after(() => {
    if (promovidos.length === 0) return
    comoAdmin()
    for (const id of promovidos) {
      cy.apiRequest({ method: 'PATCH', url: `/usuarios/${id}`, body: { perfil: 'cliente' } })
    }
  })

  it('USU 01 · páginas de 2 em 2 → total constante, sem duplicar nem omitir, página fora do intervalo vazia', () => {
    // Garante mais de uma página: três contas novas.
    cy.criarUsuarioDescartavel()
    cy.criarUsuarioDescartavel()
    cy.criarUsuarioDescartavel()
    comoAdmin()

    listar('page=1&pageSize=2').then((primeira) => {
      const { total } = primeira
      expect(total, 'há mais de uma página').to.be.greaterThan(2)
      expect(primeira.items).to.have.length(2)

      const paginas = Math.ceil(total / 2)
      const vistos = new Set(primeira.items.map((u) => u.id))

      // Percorre só as 3 primeiras e a última (a base pode ser grande).
      const alvo = [2, 3, paginas].filter((p, i, a) => p <= paginas && a.indexOf(p) === i)
      for (const pagina of alvo) {
        listar(`page=${pagina}&pageSize=2`).then((corpo) => {
          expect(corpo.total, `total na página ${pagina}`).to.eq(total)
          expect(corpo.page).to.eq(pagina)
          const esperados = pagina === paginas ? total - (paginas - 1) * 2 : 2
          expect(corpo.items).to.have.length(esperados)
          for (const u of corpo.items) {
            expect(vistos.has(u.id), `usuário repetido entre páginas: ${u.email}`).to.eq(false)
            vistos.add(u.id)
          }
        })
      }

      // Além da última: vazia e com o mesmo total.
      listar(`page=${paginas + 1}&pageSize=2`).then((corpo) => {
        expect(corpo.items).to.have.length(0)
        expect(corpo.total).to.eq(total)
      })

      // Campos do contrato presentes; nenhum segredo.
      for (const u of primeira.items) {
        expect(u).to.include.keys('id', 'nome', 'email', 'perfil', 'ativo', 'criadoEm')
        expect(JSON.stringify(u)).not.to.match(/senha|hash|password/i)
      }
    })
  })

  it('USU 02 · busca por nome, trecho, e-mail, caixa e termo inexistente → casa como contém sem diferenciar caixa; total acompanha o filtro', () => {
    const s = sufixo()
    const nome = `José Ândré ${s}`
    const email = `busca.${s}@exemplo.com`

    registrar({ nome, email, senha: SENHA_OK }).its('status').should('eq', 201)
    comoAdmin()

    const casos = [
      ['nome completo', nome],
      ['trecho do nome', `ândré ${s}`],
      ['e-mail completo', email],
      ['trecho do e-mail', `busca.${s}`],
      ['caixa alta', nome.toUpperCase()],
      ['caixa baixa', nome.toLowerCase()],
    ]
    for (const [rotulo, termo] of casos) {
      listar(`search=${encodeURIComponent(termo)}&pageSize=50`).then((corpo) => {
        expect(corpo.total, rotulo).to.eq(1)
        expect(corpo.items).to.have.length(1)
        expect(corpo.items[0].email).to.eq(email)
      })
    }

    // Inexistente: vazio, total 0.
    listar(`search=${encodeURIComponent(`nao-existe-${s}`)}`).then((corpo) => {
      expect(corpo.items).to.have.length(0)
      expect(corpo.total).to.eq(0)
    })

    // Limpar o termo devolve a lista integral (mais que o filtrado).
    listar('pageSize=1').its('total').should('be.greaterThan', 1)
  })

  it('USU 03 · cadastro de cliente → um usuário, papel Cliente, ativo, sem senha em nenhuma resposta e login funcional', () => {
    const s = sufixo()
    const email = `cliente.${s}@exemplo.com`

    registrar({ nome: `Cliente ${s}`, email, senha: SENHA_OK }).then(({ status, body }) => {
      expect(status).to.eq(201)
      expect(body.perfil).to.eq('cliente')
      expect(JSON.stringify(body)).not.to.match(/senha|hash|password/i)
      expect(JSON.stringify(body)).not.to.contain(SENHA_OK)
    })

    comoAdmin()
    listar(`search=${encodeURIComponent(email)}`).then((corpo) => {
      expect(corpo.total).to.eq(1)
      expect(corpo.items[0].perfil).to.eq('cliente')
      expect(corpo.items[0].ativo).to.eq(true)
      expect(JSON.stringify(corpo)).not.to.match(/senha|hash|password/i)
    })

    cy.clearCookies()
    cy.loginComo({ email, senha: SENHA_OK }).its('status').should('eq', 201)
    cy.apiRequest<{ email: string; perfil: string }>({ method: 'GET', url: '/auth/me' })
      .its('body')
      .should('include', { email, perfil: 'cliente' })
  })

  it('USU 04 · só o admin concede o papel Admin → cadastro não aceita papel; promoção persiste, libera a administração e o rebaixamento a retira', () => {
    const s = sufixo()

    // Quem se cadastra não escolhe o papel: ou recusa o campo, ou ignora e cria Cliente.
    registrar({
      nome: `Tentativa ${s}`,
      email: `tent.${s}@exemplo.com`,
      senha: SENHA_OK,
      perfil: 'admin',
    }).then(({ status, body }) => {
      if (status === 201) expect(body.perfil).to.eq('cliente')
      else expect(status).to.be.oneOf(RECUSADO)
    })

    cy.criarUsuarioDescartavel().then((conta) => {
      promovidos.push(conta.id)

      // Antes da promoção a administração é negada.
      cy.loginComo(conta)
      cy.apiRequest({ method: 'GET', url: '/usuarios', failOnStatusCode: false })
        .its('status')
        .should('be.oneOf', [401, 403])

      comoAdmin()
      cy.apiRequest({ method: 'PATCH', url: `/usuarios/${conta.id}`, body: { perfil: 'admin' } })
        .its('status')
        .should('be.within', 200, 204)
      listar(`search=${encodeURIComponent(conta.email)}`)
        .its('items.0.perfil')
        .should('eq', 'admin')

      // Novo login: papel persistido e administração liberada (API e tela).
      cy.clearCookies()
      cy.loginComo(conta)
      cy.apiRequest<{ perfil: string }>({ method: 'GET', url: '/auth/me' })
        .its('body.perfil')
        .should('eq', 'admin')
      cy.apiRequest({ method: 'GET', url: '/usuarios' }).its('status').should('eq', 200)
      cy.visit('/admin')
      cy.location('pathname').should('eq', '/admin')

      // Rebaixar devolve o acesso de cliente.
      comoAdmin()
      cy.apiRequest({ method: 'PATCH', url: `/usuarios/${conta.id}`, body: { perfil: 'cliente' } })
        .its('status')
        .should('be.within', 200, 204)
      cy.clearCookies()
      cy.loginComo(conta)
      cy.apiRequest({ method: 'GET', url: '/usuarios', failOnStatusCode: false })
        .its('status')
        .should('be.oneOf', [401, 403])
    })
  })

  it('USU 05 · senha com 7 caracteres, sem número, sem símbolo e válida → só a válida cria conta e a senha não volta na resposta', () => {
    const s = sufixo()
    const casos: Array<[string, string, boolean]> = [
      ['7 caracteres com número e símbolo', 'Ab1!xyz', false],
      ['8 sem número', 'Abcdefg!', false],
      ['8 sem símbolo', 'Abcdefg1', false],
      ['72 caracteres (limite)', `Aa1!${'x'.repeat(68)}`, true],
      ['73 caracteres (acima do limite)', `Aa1!${'x'.repeat(69)}`, false],
      ['8 com número e símbolo', 'Abcdef1!', true],
    ]

    casos.forEach(([rotulo, senha, aceita], i) => {
      const email = `senha.${s}.${i}@exemplo.com`
      registrar({ nome: `Senha ${i}`, email, senha }).then(({ status, body }) => {
        if (aceita) expect(status, rotulo).to.eq(201)
        else expect(status, rotulo).to.be.oneOf(RECUSADO)
        expect(JSON.stringify(body), `${rotulo}: resposta`).not.to.contain(senha)
      })
    })

    // As recusadas não deixaram conta parcial.
    comoAdmin()
    listar(`search=${encodeURIComponent(`senha.${s}`)}&pageSize=50`).then(({ items }) => {
      expect(items.map((u) => u.email).sort()).to.deep.eq(
        [`senha.${s}.3@exemplo.com`, `senha.${s}.5@exemplo.com`].sort(),
      )
    })
  })

  it('USU 06 · campos vazios, e-mail malformado e limites de tamanho → recusados sem criar cadastro parcial', () => {
    const s = sufixo()
    const base = { nome: 'Nome Válido', senha: SENHA_OK }
    const casos: Array<[string, Record<string, unknown>]> = [
      ['nome vazio', { ...base, nome: '', email: `inv.${s}.0@exemplo.com` }],
      ['sem nome', { senha: SENHA_OK, email: `inv.${s}.1@exemplo.com` }],
      ['e-mail vazio', { ...base, email: '' }],
      ['sem e-mail', { ...base }],
      ['e-mail malformado', { ...base, email: `sem-arroba-${s}` }],
      ['e-mail com espaços nas bordas', { ...base, email: ` inv.${s}.2@exemplo.com ` }],
      ['senha vazia', { nome: 'Nome Válido', email: `inv.${s}.3@exemplo.com`, senha: '' }],
      [
        'nome com 151 caracteres',
        { ...base, nome: 'N'.repeat(151), email: `inv.${s}.4@exemplo.com` },
      ],
      [
        'e-mail com mais de 255 caracteres',
        { ...base, email: `inv.${s}.${'a'.repeat(250)}@exemplo.com` },
      ],
    ]
    for (const [rotulo, corpo] of casos) {
      registrar(corpo).its('status', { log: false }).should('be.oneOf', RECUSADO)
      cy.log(`recusado: ${rotulo}`)
    }

    comoAdmin()
    listar(`search=${encodeURIComponent(`inv.${s}`)}`)
      .its('total')
      .should('eq', 0)
  })

  it('USU 06 · nome só com espaços → recusado como vazio (falha até aparar o nome no servidor)', () => {
    const s = sufixo()
    registrar({ nome: '     ', email: `espacos.${s}@exemplo.com`, senha: SENHA_OK })
      .its('status')
      .should('be.oneOf', RECUSADO)
  })

  it('USU 06 · e-mail repetido e variações de espaços → duplicado recusado (409), sem trocar a conta original', () => {
    const s = sufixo()
    const email = `dup.${s}@exemplo.com`

    registrar({ nome: 'Original', email, senha: SENHA_OK }).its('status').should('eq', 201)
    registrar({ nome: 'Cópia', email, senha: SENHA_OK }).its('status').should('eq', 409)
    registrar({ nome: 'Cópia', email: ` ${email} `, senha: SENHA_OK })
      .its('status')
      .should('be.oneOf', [400, 409])

    comoAdmin()
    listar(`search=${encodeURIComponent(email)}`).then(({ total, items }) => {
      expect(total).to.eq(1)
      expect(items[0].nome).to.eq('Original')
    })
  })

  it('USU 06 · mesmo e-mail com caixa diferente → tratado como duplicado (falha até normalizar o e-mail)', () => {
    const s = sufixo()
    const email = `Caixa.${s}@exemplo.com`

    registrar({ nome: 'Original', email, senha: SENHA_OK }).its('status').should('eq', 201)
    registrar({ nome: 'Variação', email: email.toLowerCase(), senha: SENHA_OK })
      .its('status')
      .should('eq', 409)
  })

  it('USU 07 · mesmo cadastro enviado duas vezes (retry após timeout) → um só usuário e o segundo envio recusado', () => {
    const s = sufixo()
    const corpo = { nome: `Retry ${s}`, email: `retry.${s}@exemplo.com`, senha: SENHA_OK }

    registrar(corpo).its('status').should('eq', 201)
    registrar(corpo).its('status').should('eq', 409)

    comoAdmin()
    listar(`search=${encodeURIComponent(corpo.email)}`)
      .its('total')
      .should('eq', 1)
  })
})

export {}
